chapters=[]
def C(n,title,section,day,start,end,focus,points,drugs,rehab,trap,flash,quiz,case):
 chapters.append(dict(id=n,title=title,section=section,day=day,pages=[start,end],pdfPages=[start+30,end+30],minutes=22 if end-start<18 else 28,focus=focus,points=points.split('~'),drugs=[dict(zip(['class','examples','mechanism','watch'],x.split('|'))) for x in drugs.split('~')],rehab=rehab.split('~'),trap=trap,flashcards=[dict(zip(['front','back'],x.split('|'))) for x in flash.split('~')],quiz=[dict(question=x.split('|')[0],answer=x.split('|')[1],distractors=x.split('|')[2:5],rationale=x.split('|')[5]) for x in quiz.split('~')],case=dict(zip(['scenario','question','answer'],case.split('|')))))
C(1,'Basic Principles of Pharmacology','Foundations',1,3,14,'Explain a drug response before memorizing a drug list.',
'Pharmacodynamics describes what a drug does to the body; pharmacokinetics describes how the body handles it.~A generic name identifies the active drug; several brand names can refer to the same ingredient. Reconcile ingredients to avoid accidental duplication.~Potency is the dose needed for an effect. Efficacy is the maximum effect achievable. A more potent drug is not necessarily more effective.~Dose-response curves connect dose with response. A ceiling means increasing dose no longer adds the desired effect, although toxicity may increase.~The therapeutic index compares toxic and effective doses. A narrow therapeutic margin means small exposure changes can matter.~Preclinical work and clinical trial phases examine safety and effectiveness; approval does not eliminate the need for adverse-effect monitoring. Prescription, OTC, and controlled status describe different regulatory questions.',
'Generic vs brand|Acetaminophen; multiple trade names|One active ingredient may have many labels|Check combination products~Dose-response concepts|ED50; TD50; therapeutic index|Compare effective and toxic exposure|Population averages do not guarantee individual safety',
'Obtain a complete medication and supplement history, including PRN products.~Connect a new symptom to medication changes as well as the underlying disease.~Document functional changes and communicate concerns without independently changing prescriptions.',
'Potency is not the same as efficacy or safety.',
'What is pharmacodynamics?|The actions and effects of a drug on the body.~What does potency compare?|The dose or concentration required to produce a specified effect.~Why does a narrow therapeutic index matter?|A relatively small exposure change may move a patient from benefit toward toxicity.',
'A left-shifted dose-response curve with the same maximum primarily indicates what?|Greater potency|Greater maximum efficacy|Absence of toxicity|Slower renal excretion|Less drug is needed for the same effect; the unchanged maximum does not show greater efficacy.~Two products have different brand names but the same generic ingredient. What is the main concern?|Duplicate exposure|Guaranteed therapeutic failure|Different receptor families|No possibility of interaction|Brand differences do not prevent the same ingredient from being taken twice.',
'A learner assumes the lowest-dose analgesic is always the safest.|Which two distinctions are missing?|Separate potency from efficacy, then evaluate adverse effects and the therapeutic margin. Dose size alone cannot establish safety.')
C(2,'Pharmacokinetics I: Administration, Absorption, and Distribution','Foundations',1,15,30,'Trace how an administered dose reaches its target.',
'Route changes onset, bioavailability, convenience, and risk. IV administration enters the circulation directly; oral dosing must first be absorbed.~Oral drugs may undergo first-pass metabolism in the gut wall and liver. Sublingual and transdermal routes can avoid much of this initial hepatic passage.~Membrane movement depends on lipid solubility, ionization, concentration gradients, transporters, and tissue barriers.~Bioavailability is the fraction of the dose reaching systemic circulation unchanged; it is not simply how fast a drug works.~Only unbound drug can readily leave plasma and interact with many targets. Protein binding can create a reservoir and influence interactions.~Distribution depends on perfusion, permeability, binding, and body composition. Apparent volume of distribution relates body drug amount to plasma concentration.~Fat, bone, and other tissues may store drugs and prolong effects. Controlled-release products, implanted pumps, prodrugs, and targeted delivery alter exposure patterns.',
'Enteral routes|Oral; buccal; sublingual|Absorption through GI or oral mucosa|First-pass exposure differs by route~Parenteral and topical routes|IV; IM; transdermal|Delivery without conventional swallowed absorption|Onset and local tissue effects vary~Distribution|Albumin binding; tissue storage|Partitioning between plasma and tissues|Low albumin may alter unbound exposure',
'Ask about route and formulation, not just the drug name.~Heat and exercise can alter skin and muscle perfusion, potentially changing absorption from local delivery sites.~Do not assume a patch has only local effects or that a tablet can be crushed safely.',
'Bioavailability, onset, and volume of distribution describe different properties.',
'Which route has complete systemic bioavailability by definition?|Intravenous administration.~What is first-pass metabolism?|Presystemic metabolism before an absorbed dose reaches the general circulation.~What does a large apparent volume of distribution suggest?|Much of the drug is outside the plasma relative to its measured plasma concentration.',
'Which route bypasses an absorption step into systemic circulation?|Intravenous|Oral|Intramuscular|Transdermal|IV dosing enters the bloodstream directly; the other routes require absorption.~Which fraction most readily crosses out of plasma to act at many targets?|Unbound drug|Albumin-bound drug only|All drug stored in bone|Only drug already excreted|Protein binding retains a portion within plasma; unbound drug is available for distribution.',
'A patient uses a transdermal analgesic patch and requests a hot pack over it.|What principle should guide the response?|Local heating can change absorption and systemic exposure. Check the product instructions and coordinate the treatment plan before applying heat near a drug delivery site.')
C(3,'Pharmacokinetics II: Drug Elimination','Foundations',1,31,42,'Predict accumulation and interactions from clearance.',
'Elimination combines metabolism and excretion. The liver is a major metabolic organ and the kidneys are major excretory organs.~Phase I reactions commonly modify a molecule; phase II reactions conjugate it. Metabolites may be inactive, active, or toxic.~CYP enzyme induction often lowers concentrations of susceptible active drugs; inhibition often raises them. Prodrugs can behave differently because activation may be reduced.~Renal elimination includes filtration, secretion, and reabsorption. Reduced renal function can prolong drug exposure.~Half-life is the time for concentration to fall by half in a first-order model. Repeated dosing usually approaches steady state over about four to five half-lives.~Clearance is the volume of plasma cleared of drug per unit time. With first-order kinetics, half-life is proportional to volume of distribution divided by clearance.~Age, genetic variation, disease, smoking, diet, and interacting drugs can change elimination. A loading dose and a maintenance dose address different pharmacokinetic needs.',
'Metabolic interactions|Enzyme inducers and inhibitors|Change metabolism of susceptible drugs|Direction depends on active drug vs prodrug~Renal elimination|Filtration; secretion; reabsorption|Removes drug and metabolites|Accumulation with impaired clearance',
'New sedation, confusion, or ataxia after illness may reflect accumulation rather than loss of motivation.~Flag major hydration, liver, or kidney changes to the care team.~Interpret drug timing alongside half-life and repeated dosing; effects may persist beyond the last dose.',
'A half-life does not mean the drug is completely gone after that interval.',
'How much remains after two first-order half-lives?|About one quarter of the starting concentration.~What generally happens when clearance falls and dose stays unchanged?|Exposure and risk of accumulation can increase.~How long does a typical first-order regimen take to approach steady state?|Approximately four to five half-lives.',
'After three half-lives, approximately what fraction remains?|One eighth|One half|Three quarters|None|Each half-life halves the previous amount: 1/2, 1/4, then 1/8.~An enzyme inhibitor is added to an active CYP-metabolized drug. What is a possible consequence?|Increased drug exposure|Guaranteed faster excretion|No interaction is possible|Immediate loss of all receptor binding|Reduced metabolism can increase exposure, although the specific interaction must be checked.',
'An older patient becomes progressively drowsy on an unchanged medication regimen after a decline in kidney function.|What is the pharmacokinetic concern?|Reduced clearance may allow accumulation. Record the change and request medication review; do not assume the stable prescribed dose produces stable exposure.')
C(4,'Drug Receptors','Foundations',1,43,56,'Connect receptor behavior with benefit, blockade, and tolerance.',
'Receptors recognize specific ligands and translate binding into a cellular response. They may be on the cell surface or inside the cell.~Ligand-gated ion channels act through membrane permeability; G-protein pathways use intracellular signaling; enzyme-linked and intracellular receptors use other mechanisms.~Affinity describes binding tendency; intrinsic activity describes the ability to activate a receptor after binding.~A full agonist produces a maximal response; a partial agonist has lower intrinsic activity and can limit a full agonist when both compete.~Competitive antagonism can often be overcome by more agonist. Noncompetitive or irreversible antagonism can reduce the available maximum response.~An inverse agonist reduces constitutive receptor activity; it is different from a neutral antagonist.~Repeated stimulation can cause desensitization or down-regulation. Prolonged blockade or denervation can produce supersensitivity.',
'Agonists|Full; partial; inverse|Differ in receptor activation after binding|Binding alone does not predict response~Antagonists|Competitive; noncompetitive|Reduce agonist effects by different mechanisms|Maximum response may or may not be preserved',
'Receptor adaptation helps explain tolerance and rebound after abrupt withdrawal.~Different receptor subtypes create both therapeutic selectivity and off-target effects.~Do not interpret loss of effect as an automatic indication to increase a dose.',
'An antagonist has affinity, but does not activate the receptor as an agonist does.',
'What is affinity?|The tendency of a ligand to bind a receptor.~How can a partial agonist oppose a full agonist?|It occupies receptors while producing a smaller response.~What is down-regulation?|A reduction in receptor availability or expression after sustained stimulation.',
'Which property distinguishes an agonist from a neutral antagonist?|Intrinsic activating ability|Ability to enter a tablet|Generic naming|Renal filtration alone|Both can bind, but an agonist activates the receptor.~Which adaptation can follow prolonged receptor blockade?|Supersensitivity|Permanent elimination of all receptors|Guaranteed drug tolerance through induction|Loss of every endogenous ligand|Compensatory increases in receptor number or responsiveness can increase sensitivity.',
'A drug works less well after repeated exposure.|Is receptor down-regulation the only explanation?|No. Receptor adaptation is one mechanism; altered metabolism, disease progression, adherence, and other causes also require consideration.')
C(5,'General Principles of CNS Pharmacology','Central nervous system',1,59,68,'Map neurotransmission to cognition, behavior, and movement.',
'The CNS integrates cognition, sensation, movement, and autonomic control. Drug effects depend on the neural pathways and receptors involved.~The blood-brain barrier limits CNS access; lipid solubility and transport systems influence entry and removal.~Synaptic transmission involves transmitter synthesis, storage, release, receptor activation, and signal termination.~Drugs may change transmitter synthesis or release, mimic or block receptors, or inhibit reuptake or enzymatic breakdown.~Glutamate is a major excitatory transmitter; GABA and glycine commonly mediate inhibition. The receptor and circuit determine the actual response.~Dopamine, serotonin, norepinephrine, acetylcholine, and neuropeptides influence multiple overlapping functions; one transmitter does not equal one behavior.',
'Inhibitory transmission|GABA; glycine|Often reduces neuronal excitability|Excess inhibition can impair alertness~Modulatory transmission|Dopamine; serotonin; norepinephrine|Changes signaling across CNS circuits|Motor and behavioral effects can coexist',
'Observe attention, memory, coordination, and motor learning as well as symptom relief.~Sedation can impair retention of a new mobility skill even when a patient appears calm.~Relate changes in participation to the timing of CNS medications.',
'A neurotransmitter can produce different effects at different receptor subtypes.',
'What limits many drugs from entering the brain?|The blood-brain barrier and its transport systems.~Name two ways to prolong transmitter action.|Inhibit reuptake or inhibit enzymatic breakdown.~Why can a CNS drug affect both movement and mood?|The same transmitter systems participate in multiple neural circuits.',
'Inhibiting transmitter reuptake usually does what at that synapse?|Prolongs transmitter availability|Stops all transmitter synthesis|Removes every postsynaptic receptor|Guarantees a purely inhibitory response|Less reuptake can increase synaptic availability; the resulting effect depends on receptors.~Which observation is most relevant to motor-learning carryover?|Attention and memory|Brand color|Package size|Tablet shape alone|Attention and memory determine whether instruction is retained between sessions.',
'A patient follows instructions during therapy but cannot recall them the next morning after starting a CNS medication.|What should be assessed?|Consider medication-related effects on attention and memory, compare timing and baseline function, and communicate the change to the care team.')
C(6,'Sedative-Hypnotic and Antianxiety Drugs','Central nervous system',2,69,82,'Distinguish anxiolysis from impairment.',
'Benzodiazepines enhance GABA-A-mediated inhibition and can provide anxiolysis, sedation, hypnosis, anticonvulsant effects, and muscle relaxation.~Barbiturates also enhance inhibition but have a less favorable safety profile and important interactions.~Zolpidem, zaleplon, and eszopiclone act at the GABA-A receptor complex; ramelteon acts at melatonin receptors.~Buspirone acts through serotonergic mechanisms and does not provide immediate benzodiazepine-like relief. Some antidepressants also treat anxiety.~Residual next-day sedation, impaired memory, ataxia, and slower reactions can interfere with rehabilitation.~Dependence and withdrawal are distinct from symptom relief. Abrupt withdrawal after sustained use can be hazardous.~Combining CNS depressants can intensify sedation and respiratory impairment. Sleep hygiene and behavioral measures remain relevant.',
'Benzodiazepines|Diazepam; lorazepam; temazepam|Enhance GABA-A effects|Sedation, falls, dependence~Other hypnotics|Zolpidem; ramelteon|GABA-A modulation or melatonin receptor activation|Residual impairment; agent-specific sleep behaviors~Nonbenzodiazepine anxiolytic|Buspirone|Serotonergic activity|Delayed benefit; dizziness',
'Assess wakefulness and balance before transfers or gait training.~Schedule demanding learning when residual sedation is lowest, in coordination with the team.~Do not interpret reduced anxiety as proof that the patient can safely perform unsupervised mobility.',
'A nonbenzodiazepine label does not mean an absence of sedation or fall risk.',
'What receptor system do benzodiazepines enhance?|GABA-A-mediated inhibitory transmission.~Why may a bedtime hypnotic affect morning therapy?|Long duration or active metabolites can cause residual impairment.~Does buspirone act as immediate rescue sedation?|No; its anxiolytic benefit develops over time.',
'Which finding most directly suggests residual hypnotic impairment?|Morning drowsiness and poor recall|Improved visual acuity|New bone formation|Increased platelet production|Sedation and memory impairment can persist into the next day.~Which combination raises concern for additive CNS depression?|A benzodiazepine with an opioid|A benzodiazepine with a label change|Buspirone with a notebook|Ramelteon with a gait belt|Both a benzodiazepine and an opioid can suppress CNS function.',
'A patient is very drowsy during morning transfer training after a long-acting sleep drug.|What is the study takeaway?|Residual sedation can impair safety and learning. Assess alertness, protect mobility, document the pattern, and coordinate medication and session timing with the team.')
C(7,'Drugs for Depression and Bipolar Disorder','Central nervous system',2,83,100,'Compare antidepressant mechanisms and mood-stabilizer monitoring.',
'SSRIs inhibit serotonin reuptake; SNRIs inhibit serotonin and norepinephrine reuptake. Clinical mood improvement is delayed relative to the initial synaptic effect.~Tricyclic antidepressants have anticholinergic, sedating, orthostatic, and cardiac effects in addition to monoamine reuptake inhibition.~MAO inhibitors reduce monoamine breakdown and have important food and drug interactions.~Lithium is a mood stabilizer with a narrow therapeutic range. Hydration, sodium balance, kidney function, and interacting drugs affect toxicity risk.~Some anticonvulsants and atypical antipsychotics also have roles in bipolar disorder.~Watch for tremor, ataxia, confusion, marked behavioral change, and problems with thermoregulation or orthostatic tolerance.~Improved mood can improve participation, but pain treatment with an antidepressant does not by itself establish a psychiatric diagnosis.',
'SSRIs and SNRIs|Fluoxetine; sertraline; venlafaxine|Reduce monoamine reuptake|GI effects; agent-specific activation or sedation~Older antidepressants|Amitriptyline; phenelzine|Reuptake inhibition or MAO inhibition|Orthostasis; anticholinergic effects; interactions~Mood stabilizer|Lithium|Multiple effects on intracellular and neuronal signaling|Narrow margin; renal and fluid-balance sensitivity',
'Check postural symptoms and cognition when progressing mobility.~Report new tremor, coordination problems, or confusion in a patient taking lithium.~Discuss heat exposure, hydration changes, and exercise tolerance with the supervising team.',
'The rapid change in neurotransmitter availability does not imply immediate antidepressant benefit.',
'Why can a tricyclic increase fall risk?|Sedation and orthostatic hypotension can impair safe mobility.~Why does hydration matter with lithium?|Fluid and sodium changes can affect renal handling and concentration.~Can antidepressants be used for pain?|Yes; some are used in selected pain syndromes as well as mood disorders.',
'Which drug requires particular attention to sodium and fluid balance?|Lithium|Topical miconazole|Inhaled cromolyn|A calcium-containing antacid alone|Lithium handling is sensitive to kidney function and sodium-water balance.~Which effect can make tricyclic therapy relevant during standing practice?|Orthostatic hypotension|Guaranteed increased bone density|Selective paralysis|Immediate antibiotic resistance|Postural blood-pressure drops can cause dizziness and falls.',
'A patient taking lithium develops new coarse tremor and unsteady walking during a hot week.|What concern should be communicated?|Possible toxicity or altered exposure related to fluid balance requires prompt medical review; the therapist should document findings and avoid treating this as routine deconditioning.')
C(8,'Antipsychotic Drugs','Central nervous system',2,101,114,'Recognize medication-related movement disorders.',
'Antipsychotics reduce psychotic symptoms and may improve organized behavior, self-care, and cooperation.~Many traditional agents prominently block dopamine D2 receptors; atypical agents have differing dopamine and serotonin actions.~Dopamine pathway effects can cause acute dystonia, akathisia, parkinsonism, and tardive dyskinesia. Their patterns and timing differ.~Tardive dyskinesia may involve repetitive mouth, tongue, facial, or limb movements and can persist after treatment changes.~Sedation, anticholinergic effects, orthostatic hypotension, and metabolic effects vary by agent.~Fever, severe rigidity, altered mental status, and autonomic instability raise concern for neuroleptic malignant syndrome and require emergency escalation.~Do not assume every new motor symptom represents progression of the primary neurological condition.',
'Traditional antipsychotics|Haloperidol; chlorpromazine|Prominent dopamine receptor antagonism|Extrapyramidal effects and orthostasis~Atypical antipsychotics|Clozapine; risperidone; olanzapine|Differing dopamine and serotonin effects|Agent-specific metabolic and other serious effects',
'Observe posture, gait, restlessness, and involuntary movements over time.~Guard against postural hypotension during early treatment or dose changes.~Escalate acute rigidity with fever or altered consciousness immediately through the facility emergency process.',
'Akathisia is not simply poor cooperation, and tardive dyskinesia is not ordinary tremor.',
'What is akathisia?|A distressing sense of motor restlessness with difficulty remaining still.~What may tardive dyskinesia look like?|Repetitive involuntary facial, oral, tongue, or limb movements.~Which symptom cluster suggests neuroleptic malignant syndrome?|Fever, severe rigidity, mental-status change, and autonomic instability.',
'New repetitive tongue and chewing movements during chronic antipsychotic exposure suggest what?|Tardive dyskinesia|Simple muscle hypertrophy|Improved coordination|Acute hypoglycemia by definition|The movement pattern is characteristic of tardive dyskinesia and needs medical assessment.~Which presentation needs emergency escalation?|Fever with severe rigidity and confusion|Mild dry mouth alone|Stable symptom control|Improved instruction following|This cluster may represent neuroleptic malignant syndrome.',
'A long-term antipsychotic user develops repeated lip smacking and finger movements.|Why should the therapist report this early?|Possible tardive dyskinesia may persist and warrants prompt prescriber assessment rather than being accepted as a harmless habit.')
C(9,'Antiepileptic Drugs','Central nervous system',2,115,130,'Link seizure control, adverse effects, and functional safety.',
'Antiseizure drugs suppress excessive neural firing or propagation; controlling seizures is not the same as curing the underlying disorder.~Mechanisms include voltage-gated sodium or calcium channel effects, enhancement of GABA transmission, and modulation of synaptic release.~Selection depends on seizure type, adverse effects, interactions, and patient factors; one drug is not appropriate for every seizure pattern.~Traditional examples include phenytoin, carbamazepine, valproate, phenobarbital, and ethosuximide. Newer examples include lamotrigine, levetiracetam, gabapentin, and pregabalin.~Sedation, dizziness, ataxia, cognitive effects, and agent-specific skin or systemic reactions can affect mobility and learning.~Some agents have nonlinear kinetics or major enzyme interactions. Several are also used for neuropathic pain or mood disorders.~Long-term treatment can influence bone health; seizure history and adherence remain important even when referral is for an unrelated problem.',
'Sodium-channel related agents|Phenytoin; carbamazepine; lamotrigine|Limit repetitive neuronal firing|Ataxia; dizziness; agent-specific rash~Other antiseizure mechanisms|Valproate; levetiracetam; gabapentin|Different inhibitory and synaptic effects|Sedation and agent-specific interactions',
'Know the individual seizure response plan and maintain a safe treatment environment.~Compare coordination and alertness with the dosing schedule.~Report increased seizures or new toxicity features; never advise abrupt discontinuation.',
'An antiseizure prescription does not prove the patient has epilepsy; it may be used for pain or mood.',
'Why is seizure type important?|Drug effectiveness and possible worsening vary across seizure types.~Which adverse effect can mimic cerebellar dysfunction?|Drug-related ataxia.~Why review long-term bone health?|Some chronic antiseizure regimens can contribute to reduced bone health and fracture risk.',
'Which new finding can interfere directly with gait safety during antiseizure therapy?|Ataxia|More readable labels|Increased tablet weight|Generic substitution by name alone|Coordination impairment can result from adverse drug effects.~A patient takes gabapentin. What should you establish before assuming epilepsy?|The indication for treatment|The color of the capsule|The pharmacy logo|Whether the name has three syllables|Gabapentin may be prescribed for neuropathic pain and other indications.',
'A patient treated for neuralgia becomes unsteady after a medication increase.|What should the therapist consider?|An antiseizure drug used for pain may still cause sedation or ataxia. Compare the onset with the change and communicate functional consequences.')
C(10,'Pharmacological Management of Parkinson Disease','Central nervous system',2,131,148,'Use the dopamine model to understand motor fluctuations.',
'Loss of dopaminergic neurons in the substantia nigra alters basal-ganglia signaling and contributes to bradykinesia, rigidity, and tremor.~Levodopa crosses into the CNS and is converted to dopamine. Carbidopa reduces peripheral conversion, improving delivery and reducing peripheral effects.~Dopamine agonists stimulate receptors directly; MAO-B and COMT inhibitors prolong dopaminergic effects through different sites of action.~Amantadine and selected anticholinergic agents act through other mechanisms; benefit and adverse effects differ by symptom and patient.~Wearing-off is a return of symptoms as a dose effect wanes; on-off fluctuations can be less predictable. Dyskinesia is excessive involuntary movement, not simply improved mobility.~Orthostatic hypotension, nausea, hallucinations, somnolence, and cognitive effects can limit function.~Motor improvement does not remove balance, freezing, or fall risks; therapy should use the patient’s observed response pattern.',
'Dopamine replacement|Levodopa plus carbidopa|Replenishes CNS dopamine while reducing peripheral breakdown|Fluctuations; dyskinesia; orthostasis~Adjunct dopaminergic drugs|Pramipexole; selegiline; entacapone|Stimulate receptors or prolong dopamine-related action|Sleepiness; hallucinations; interactions~Other mechanisms|Amantadine; selected anticholinergics|Modulate nondopaminergic signaling|Cognitive and anticholinergic burdens',
'Record when useful mobility occurs relative to actual dosing.~Practice demanding tasks during observed periods of useful response, while guarding for dyskinesia.~Use postural blood-pressure and symptom monitoring when indicated.',
'Carbidopa is not the main agent restoring dopamine inside the brain.',
'Why combine carbidopa with levodopa?|To reduce peripheral levodopa conversion and improve CNS delivery.~What is wearing-off?|Motor benefit fades as the dose effect declines.~Why track an on-off diary?|It helps align functional training with the individual response pattern.',
'Which drug is converted to dopamine within the CNS?|Levodopa|Carbidopa alone|Naloxone|Warfarin|Levodopa is the dopamine precursor; carbidopa chiefly acts peripherally.~A patient has excessive involuntary movement at peak benefit. What term fits?|Dyskinesia|Complete paralysis|Antibacterial resistance|Simple wearing-off only|Dyskinesia describes involuntary movement that can accompany dopaminergic treatment.',
'A patient walks well after medication but freezes later in the session.|How should the study coach frame the problem?|Consider motor fluctuations, document dose and symptom timing, and adapt supervised training rather than assuming inconsistent effort.')
C(11,'General Anesthetics','Anesthesia and muscle',3,149,164,'Understand recovery after global CNS depression.',
'General anesthesia produces reversible unconsciousness and components of amnesia, analgesia, and immobility; balanced anesthesia uses several agents to achieve these goals.~Inhaled agents and IV agents differ in delivery, uptake, recovery, and adverse effects.~Blood-gas solubility influences how quickly inhaled anesthetic partial pressures change. Lower solubility generally permits faster induction and recovery under comparable conditions.~Minimum alveolar concentration is an inhaled potency measure; it is not a direct measure of all aspects of safety.~Cardiorespiratory depression, postoperative nausea, confusion, and residual impairment can complicate recovery.~Neuromuscular blockers may be adjuncts for surgery but do not themselves provide consciousness loss or pain relief.~Inherited susceptibility to malignant hyperthermia is associated with selected anesthetic triggers and is a medical emergency.',
'Inhaled anesthetics|Sevoflurane; isoflurane; nitrous oxide|Reversible CNS effects through multiple targets|Cardiorespiratory effects and recovery profile~IV anesthetics|Propofol; etomidate; ketamine|Different CNS targets and anesthetic profiles|Hemodynamic, emergence, and airway considerations',
'Confirm postoperative alertness, respiratory stability, and mobility clearance before treatment.~Distinguish residual anesthetic impairment from the surgical impairment.~Coordinate early mobilization with the perioperative team and monitor response.',
'Immobility from a neuromuscular blocker does not mean analgesia or unconsciousness.',
'What is balanced anesthesia?|Combining agents to provide complementary anesthetic effects.~What does MAC primarily compare?|Inhaled anesthetic potency under standardized conditions.~Why assess postoperative cognition?|Residual drug effects can impair instruction following and safe mobility.',
'Which statement about neuromuscular blockers is correct?|They do not independently provide analgesia or unconsciousness|They always provide complete amnesia|They replace every anesthetic|They are ordinary oral antidepressants|Paralysis must be distinguished from anesthesia and analgesia.~Lower blood-gas solubility generally supports what?|Faster changes in anesthetic effect|Guaranteed absence of adverse effects|Permanent anesthesia|Inability to administer by inhalation|Less dissolved blood reservoir allows alveolar and brain partial pressures to change faster.',
'A postoperative patient is awake but inattentive and unsteady.|What matters before ambulation?|Assess recovery and safety with the team; wakefulness alone does not establish full recovery of cognition, balance, or cardiorespiratory function.')
C(12,'Local Anesthetics','Anesthesia and muscle',3,165,176,'Explain regional loss of sensation and its precautions.',
'Local anesthetics inhibit voltage-gated sodium channels, preventing action-potential propagation in exposed nerves.~Routes include topical application, local infiltration, peripheral nerve blocks, and neuraxial techniques.~Ester and amide agents differ in metabolism and some adverse-effect patterns. Lidocaine and bupivacaine are amide examples.~Onset and effectiveness depend on tissue conditions, nerve characteristics, concentration, and delivery site; acidic inflamed tissue can reduce effectiveness.~A vasoconstrictor may prolong local action and reduce systemic uptake, but local circulation and the clinical context matter.~Regional anesthesia can impair protective sensation and sometimes motor function. Systemic toxicity can affect the CNS and heart.~Iontophoresis and phonophoresis aim to assist local delivery, but delivery efficacy and safety depend on the actual drug and method.',
'Amide local anesthetics|Lidocaine; bupivacaine|Block neuronal sodium channels|Systemic CNS and cardiac toxicity if exposure is excessive~Ester local anesthetics|Procaine; tetracaine|Block neuronal sodium channels|Metabolism and hypersensitivity considerations',
'Protect an insensate region from burns, pressure, and unrecognized injury.~Check strength and sensation before weight bearing after a regional block.~Avoid assuming that reduced pain means the tissue has recovered or can tolerate aggressive loading.',
'A numb limb can still be injured; analgesia does not restore protective feedback.',
'Which ion channel is the main target?|Voltage-gated sodium channels.~Why protect anesthetized skin from heat?|Loss of sensation reduces warning of a thermal injury.~Does a nerve block always preserve motor function?|No; motor impairment depends on the block and exposure.',
'What directly prevents nerve conduction with a local anesthetic?|Sodium-channel blockade|Increased platelet synthesis|Activation of vitamin D|Inhibition of gastric acid alone|Blocking sodium current interrupts action-potential propagation.~After a lower-limb block, what should precede walking?|Assessment of motor and sensory recovery|Assuming pain relief means normal strength|Removing every safety aid|Testing heat tolerance with a hot pack|Both protective sensation and motor control may be reduced.',
'A patient reports no knee pain after a nerve block and wants to walk alone.|Why is pain relief insufficient?|The block may also reduce sensation or motor control. Follow mobility clearance and assess function before supervised progression.')
C(13,'Skeletal Muscle Relaxants','Anesthesia and muscle',3,179,198,'Separate muscle spasm from neurological spasticity.',
'Musculoskeletal spasm and CNS-related spasticity have different mechanisms and treatment goals.~Centrally acting antispasm drugs may reduce discomfort partly through sedation; lower tone does not automatically improve function.~Baclofen is a GABA-B agonist acting mainly at spinal pathways; intrathecal delivery can focus spinal effects but requires pump monitoring.~Dantrolene acts directly on skeletal-muscle calcium release. Tizanidine is an alpha-2 agonist with central antispastic effects.~Botulinum toxin inhibits acetylcholine release at targeted neuromuscular junctions, producing focal weakness useful for selected goals.~Diazepam may reduce spasticity but sedation and dependence limit use. Neuromuscular blocking drugs used in surgery have a separate role.~Adverse effects include weakness, sedation, and agent-specific hypotension or liver toxicity; sudden interruption of baclofen can be dangerous.',
'Central antispastic agents|Baclofen; tizanidine; diazepam|Reduce excitatory motor output through different pathways|Weakness; sedation; hypotension~Peripheral agents|Dantrolene; botulinum toxin|Reduce calcium release or acetylcholine release|Generalized or focal weakness; agent-specific toxicity~Antispasm drugs|Cyclobenzaprine; methocarbamol|Central actions for musculoskeletal spasm|Sedation; limited functional benefit in some patients',
'Assess transfers, gait, and ADLs after tone changes; some tone may have supported a task.~Pair focal treatment with stretching, motor practice, and goal-based reassessment.~Urgently escalate sudden severe rebound symptoms or suspected pump interruption.',
'A lower spasticity score is not the same as better independence.',
'Where does dantrolene act?|Within skeletal muscle on calcium release.~What receptor does baclofen activate?|GABA-B receptors.~How does botulinum toxin reduce activation?|It inhibits acetylcholine release at the neuromuscular junction.',
'Which agent acts directly within skeletal muscle rather than primarily in the CNS?|Dantrolene|Baclofen|Diazepam|Tizanidine|Dantrolene reduces calcium release in skeletal muscle.~Why reassess transfers after increasing an antispastic drug?|Reduced tone and weakness may worsen a previously supported task|All tone reductions guarantee independence|The drug directly heals every contracture|Only a lab value can assess function|Functional tradeoffs matter because tone may have assisted stability or movement.',
'A patient has less leg spasticity but can no longer complete transfers after treatment escalation.|What should be reviewed?|The balance between useful tone reduction and loss of strength or compensatory tone. Share functional findings with the prescribing team.')
C(14,'Opioid Analgesics','Pain and inflammation',3,201,218,'Balance pain relief with respiratory and functional monitoring.',
'Opioids act at opioid receptors to alter nociceptive transmission and pain perception; mu-receptor effects are especially important.~Analgesia can improve participation but does not reverse the tissue lesion causing pain.~Sedation, respiratory depression, nausea, constipation, urinary retention, and orthostatic effects can limit function.~Tolerance, physical dependence, and substance-use disorder are different concepts and should not be used interchangeably.~Agonists, partial agonists, mixed agents, and antagonists have different clinical profiles. Naloxone antagonizes opioid effects.~Combining an opioid with another CNS depressant can worsen sedation and breathing impairment.~Monitor observable function and breathing; never equate an apparently sleeping patient with a safely sedated patient.',
'Opioid agonists|Morphine; fentanyl; oxycodone|Activate opioid receptors|Respiratory depression; sedation; constipation~Partial or mixed agents|Buprenorphine; selected mixed agonist-antagonists|Different receptor activity profiles|Interactions and withdrawal considerations~Antagonists|Naloxone; naltrexone|Block opioid receptor effects|Reversal and withdrawal concerns',
'Time activity with useful analgesia while checking alertness and respiratory status.~Protect against falls and constipation-related functional limitations.~If a patient is difficult to arouse or has impaired breathing, stop therapy and activate urgent help.',
'Tolerance is not proof of addiction, and effective analgesia does not eliminate overdose risk.',
'What is a major life-threatening opioid effect?|Respiratory depression.~Why can analgesia help rehabilitation?|It may allow movement, sleep, and participation with less pain.~What is physical dependence?|Physiological adaptation that can produce withdrawal when exposure is abruptly reduced.',
'Which finding needs urgent escalation in a patient receiving opioids?|Difficulty arousing with slowed breathing|Stable pain relief with normal alertness|Mild controlled constipation|A different generic label alone|Reduced responsiveness with breathing impairment can signal dangerous opioid effects.~Which drug is an opioid antagonist?|Naloxone|Morphine|Fentanyl|Oxycodone|Naloxone blocks opioid receptors and can reverse opioid effects.',
'A patient after surgery is unusually unresponsive before therapy.|What takes priority over mobilization?|Immediate assessment and emergency escalation for possible respiratory/CNS depression; medication timing is not a reason to continue treatment through unsafe sedation.')
C(15,'Nonsteroidal Anti-Inflammatory Drugs','Pain and inflammation',3,219,236,'Differentiate analgesia, anti-inflammatory action, and toxicity.',
'NSAIDs inhibit cyclooxygenase and reduce prostaglandin synthesis, producing analgesic, antipyretic, and anti-inflammatory effects.~COX-1 contributes to protective gastric and platelet functions; COX-2 contributes to inflammatory signaling but also has physiological roles.~Aspirin irreversibly inhibits platelet function. Most other NSAIDs have reversible platelet effects and should not be assumed equivalent.~Important harms include GI injury or bleeding, renal effects, fluid retention, and cardiovascular risks that vary by agent and patient.~COX-2 selectivity may reduce some GI effects but does not eliminate GI, renal, or cardiovascular risk.~Acetaminophen is analgesic and antipyretic with little clinically useful peripheral anti-inflammatory action; excessive exposure can injure the liver.~OTC products can duplicate NSAIDs or acetaminophen, especially in combination cold and pain preparations.',
'Nonselective NSAIDs|Ibuprofen; naproxen; aspirin|Reduce COX-derived prostaglandins|GI bleeding; kidney effects; fluid retention~COX-2-selective NSAID|Celecoxib|Preferential COX-2 inhibition|Cardiovascular and renal concerns remain~Non-NSAID analgesic|Acetaminophen|Analgesia and antipyresis with limited anti-inflammatory effect|Hepatic toxicity with excessive exposure',
'Report unexplained bruising, black stools, edema, or marked changes in exercise tolerance.~Ask about nonprescription use and duplicate ingredients.~Pain reduction should not justify overloading injured tissue.',
'Acetaminophen is not an interchangeable anti-inflammatory substitute for an NSAID.',
'What enzyme family do NSAIDs inhibit?|Cyclooxygenase enzymes.~Why is acetaminophen different from NSAIDs?|It has little useful peripheral anti-inflammatory action and a different toxicity profile.~Does COX-2 selectivity remove kidney risk?|No; renal and other risks remain.',
'Which drug has little clinically useful peripheral anti-inflammatory action?|Acetaminophen|Ibuprofen|Naproxen|Aspirin|Acetaminophen reduces pain and fever but is not a conventional anti-inflammatory NSAID.~Which effect distinguishes aspirin at platelets?|Irreversible COX inhibition|Permanent beta-receptor activation|Direct clot dissolution|Selective stimulation of insulin release|Aspirin irreversibly inhibits platelet COX; it does not dissolve an existing clot.',
'A patient calls an acetaminophen product an anti-inflammatory and takes a second cold medicine containing it.|What should be clarified?|Identify the active ingredients, the difference from NSAIDs, and the duplicate exposure concern, then refer medication questions to the pharmacist or prescriber.')
C(16,'Rheumatoid Arthritis and Osteoarthritis Pharmacology','Pain and inflammation',3,237,260,'Distinguish symptom control from disease modification.',
'RA is an inflammatory autoimmune joint disorder; OA involves degenerative joint changes with different treatment goals.~NSAIDs can reduce pain and inflammation but do not substitute for RA disease-modifying therapy.~Conventional DMARDs, such as methotrexate, modify disease activity. Their benefit is not the same as immediate analgesia.~Biological agents target immune pathways, such as TNF signaling; infection and other agent-specific toxicities require monitoring.~Glucocorticoids suppress inflammation quickly but chronic exposure can cause muscle wasting, bone loss, fragile skin, and adrenal suppression.~OA medication strategies principally address symptoms; the chapter discusses analgesics, NSAIDs, injections, and viscosupplementation.~Medication relief should support appropriately graded activity, joint protection, and function; it does not prove joint tissue is resistant to stress.',
'Conventional DMARDs|Methotrexate; sulfasalazine; hydroxychloroquine|Modify inflammatory disease activity through different pathways|Agent-specific marrow, hepatic, or ocular monitoring~Biological DMARDs|Etanercept; infliximab; adalimumab|Target selected inflammatory pathways|Infection and immune effects~Symptom control|NSAIDs; glucocorticoids; acetaminophen for selected pain|Reduce symptoms through different mechanisms|Do not confuse relief with structural protection',
'Watch for infection signs in patients on immune-modifying treatment.~Use joint protection and graded strengthening despite improved pain.~Consider steroid-related skin, muscle, and bone vulnerability before forceful interventions.',
'An NSAID reduces symptoms; a DMARD addresses disease activity in RA.',
'What does DMARD mean?|Disease-modifying antirheumatic drug.~Why is chronic steroid use relevant to rehabilitation?|It may weaken muscle and bone and make skin fragile.~Are OA and RA pharmacological goals identical?|No; RA requires attention to autoimmune disease modification, while OA management is largely symptomatic.',
'Which intervention addresses RA disease activity rather than only pain?|A DMARD such as methotrexate|An isolated analgesic effect|A tablet brand change|Stopping all exercise|DMARDs can modify inflammatory disease progression rather than simply relieve pain.~Which finding fits chronic glucocorticoid effects?|Muscle wasting and fragile skin|Guaranteed tissue strengthening|Permanent infection protection|Absence of fracture risk|Chronic glucocorticoids can have catabolic effects on muscle, skin, and bone.',
'A patient with RA has excellent pain relief but new bruising and proximal weakness on long-term steroids.|What should change in the review plan?|Review steroid adverse effects, protect vulnerable tissues, document weakness, and coordinate with the team rather than increasing loading solely because pain is reduced.')
C(17,'Patient-Controlled Analgesia','Pain and inflammation',3,261,276,'Understand demand dosing and its safety limits.',
'PCA lets a patient request small programmed analgesic doses through a pump; routes can include IV or neuraxial delivery.~Demand dose, lockout interval, optional basal infusion, and overall limits are different settings.~A lockout interval reduces repeated dosing but does not guarantee safety if programming, drug concentration, or patient selection is inappropriate.~A patient must be capable of understanding and using the device. Other people should not press the demand button for a sleeping patient.~Opioid PCA still carries sedation and respiratory-depression risk. Neuraxial mixtures may also affect sensation, strength, or blood pressure.~Benefits include more individualized pain control and potentially improved participation; monitoring and trained oversight remain essential.',
'PCA opioids|Morphine; fentanyl; other prescribed opioids|Programmed patient-triggered analgesic delivery|Sedation and respiratory depression~Neuraxial PCA|Opioid and/or local anesthetic regimens|Analgesia delivered near spinal pathways|Motor/sensory change; hypotension; catheter issues',
'Coordinate activity around effective, prescribed analgesia without altering pump settings.~Check alertness, breathing, and motor/sensory status where relevant.~Escalate unsafe sedation, device concerns, or unexpected weakness to the responsible team.',
'PCA by proxy defeats the safety premise of an awake patient controlling demand doses.',
'What does a lockout interval do?|Prevents another demand dose from being delivered during the programmed interval.~Who should press a patient-controlled demand button?|The appropriately assessed patient, following the prescribed plan.~Does a lockout prevent every overdose?|No; other settings, drug factors, and patient factors still matter.',
'Which action conflicts with the usual safety principle of PCA?|A relative presses for a sleeping patient|The patient requests a permitted dose|A clinician checks alertness|Staff verify the prescribed settings|Proxy dosing can deliver medication when the patient cannot self-limit because of sedation.~What should you do if the PCA patient is difficult to arouse?|Stop therapy and urgently alert the clinical team|Begin unsupervised walking|Increase the pump rate|Assume a lockout proves safety|Reduced consciousness may signal dangerous drug effects despite programmed safeguards.',
'A relative reports repeatedly pressing the PCA button while the patient sleeps.|What is the priority?|Escalate immediately to the nursing or pain team, assess patient safety through the clinical response process, and explain that demand control belongs to the assessed patient.')
C(18,'Introduction to Autonomic Pharmacology','Autonomic and cardiovascular',4,279,288,'Build the receptor map used throughout cardiovascular pharmacology.',
'The autonomic nervous system regulates involuntary functions through sympathetic and parasympathetic divisions.~All autonomic preganglionic neurons use acetylcholine at nicotinic receptors in ganglia.~Most parasympathetic postganglionic effects use acetylcholine at muscarinic receptors. Most sympathetic postganglionic effects use norepinephrine at adrenergic receptors.~Sympathetic cholinergic innervation of sweat glands is a key exception to the simple norepinephrine rule.~Alpha-1 activation commonly contracts vascular smooth muscle; beta-1 activation increases cardiac activity; beta-2 activation relaxes bronchial smooth muscle.~Muscarinic cardiac activation slows rate, while muscarinic effects in glands and GI smooth muscle increase secretion and motility.~Drug action must be interpreted by receptor subtype, location, and whether the agent is an agonist or antagonist.',
'Cholinergic receptors|Nicotinic; muscarinic|Respond to acetylcholine in different locations|Ganglionic vs effector-organ effects~Adrenergic receptors|Alpha-1; alpha-2; beta-1; beta-2|Respond to catecholamine signaling|Subtype and tissue determine response',
'Use the receptor map to predict postural blood pressure, heart-rate, sweating, and airway changes.~Review multiple autonomic drugs together because effects can add or oppose one another.~Do not assume sympathetic activation produces the same direction of effect in every organ.',
'Sympathetic does not always mean contraction; beta-2 activation relaxes bronchial smooth muscle.',
'What transmitter is used by autonomic preganglionic neurons?|Acetylcholine.~Which receptor is strongly associated with cardiac stimulation?|Beta-1.~What is a major sympathetic cholinergic exception?|Sweat glands receive sympathetic cholinergic input.',
'Which receptor activation most directly produces bronchodilation?|Beta-2|Alpha-1|Nicotinic at a skeletal motor end plate|Cardiac muscarinic only|Beta-2 activation relaxes bronchial smooth muscle.~Which transmitter is released by autonomic preganglionic neurons?|Acetylcholine|Dopamine only|Histamine only|Insulin|Both sympathetic and parasympathetic preganglionic neurons release acetylcholine.',
'A learner predicts every sympathetic drug will raise blood pressure and tighten airways.|How should the prediction be corrected?|Start with receptor subtype and location: alpha-1, beta-1, beta-2, and central alpha-2 effects are not interchangeable.')
C(19,'Cholinergic Drugs','Autonomic and cardiovascular',4,289,300,'Predict effects of increasing or blocking acetylcholine.',
'Direct cholinergic agonists activate receptors; acetylcholinesterase inhibitors indirectly increase acetylcholine by slowing its breakdown.~Muscarinic stimulation can increase GI and bladder activity, gland secretion, and bronchial smooth-muscle activity, and slow the heart.~Acetylcholinesterase inhibitors can improve neuromuscular transmission in myasthenia gravis and have other indication-specific uses.~Antimuscarinics block selected parasympathetic effector responses; examples are used in bladder, airway, eye, and movement disorders.~Antimuscarinic adverse effects include dry mouth, blurred vision, constipation, urinary retention, impaired sweating, and confusion in susceptible patients.~Nicotinic neuromuscular blockers act at skeletal motor end plates and are distinct from antimuscarinic drugs.~Both excessive cholinergic stimulation and inadequate treatment can cause weakness in particular contexts; symptoms require clinical evaluation.',
'Cholinergic stimulants|Bethanechol; pyridostigmine; donepezil|Direct receptor stimulation or acetylcholinesterase inhibition|Secretions; bradycardia; GI effects~Antimuscarinics|Atropine; oxybutynin; ipratropium|Block muscarinic receptor activity|Dryness; urinary retention; heat intolerance~Neuromuscular blockers|Rocuronium; succinylcholine|Alter nicotinic motor-end-plate transmission|Paralysis without analgesia',
'Consider impaired sweating and heat tolerance before hot environments or strenuous sessions.~In myasthenia gravis, relate activity to observed strength and medication timing with the clinical team.~Watch for anticholinergic cognitive or visual effects that interfere with ADLs.',
'Anticholinergic effects at muscarinic receptors are not identical to nicotinic neuromuscular blockade.',
'How does an acetylcholinesterase inhibitor increase activity?|It slows acetylcholine breakdown at synapses.~Why can an antimuscarinic increase heat risk?|It may reduce sweating.~Why is pyridostigmine used in myasthenia gravis?|It increases acetylcholine availability at the neuromuscular junction.',
'Which pattern fits antimuscarinic effects?|Dry mouth and reduced sweating|Excess salivation and diarrhea|Guaranteed increased bladder emptying|Universal skeletal paralysis|Blocking muscarinic effects can reduce secretions and sweating.~What is the mechanism of pyridostigmine?|Acetylcholinesterase inhibition|Direct insulin release only|COX-2 activation|Vitamin K blockade|Slower acetylcholine breakdown supports neuromuscular transmission.',
'A patient taking an overactive-bladder medication becomes unusually hot and dry during exercise.|Which drug effect belongs in the differential?|Antimuscarinic impairment of sweating. Stop and assess the response, cool as appropriate, and escalate concerning symptoms rather than attributing all symptoms to fitness.')
C(20,'Adrenergic Drugs','Autonomic and cardiovascular',4,301,314,'Predict cardiovascular and airway effects from receptor selectivity.',
'Adrenergic agonists may act directly at receptors or indirectly increase catecholamine activity.~Alpha-1 agonists increase vascular tone; alpha-1 antagonists reduce it and may cause postural hypotension.~Central alpha-2 agonists can reduce sympathetic outflow; activation of an adrenergic receptor does not always increase overall sympathetic activity.~Beta-1 agonists stimulate cardiac rate and contractility. Beta blockers reduce selected cardiac responses.~Beta-2 agonists relax airway smooth muscle; tremor and tachycardia can accompany their use.~Nonselective beta blockers can impair bronchodilation. Beta-1 selectivity is relative and dose-dependent rather than absolute.~Clinical uses span blood-pressure management, cardiac disease, asthma, and other conditions, depending on the agent.',
'Alpha-acting drugs|Phenylephrine; clonidine; prazosin|Subtype-specific vascular or central effects|Hypertension or orthostasis depending on action~Beta agonists|Dobutamine; albuterol|Beta-1 cardiac stimulation or beta-2 bronchodilation|Tachycardia; tremor~Beta antagonists|Metoprolol; propranolol|Reduce beta-mediated responses|Blunted exercise heart rate; bronchial risk with nonselective agents',
'Use perceived exertion and clinical monitoring when beta blockade blunts heart-rate response.~Monitor postural symptoms with alpha-1 blockade.~Report new wheeze or unexpected activity intolerance when the medication profile could contribute.',
'Cardioselective does not mean absolutely free of beta-2 effects.',
'What does a beta-2 agonist do in airways?|Relaxes bronchial smooth muscle.~Why may target heart rate mislead during beta blockade?|The chronotropic response is reduced.~What can an alpha-1 blocker cause on standing?|Orthostatic hypotension.',
'Why might propranolol contribute to wheezing?|It blocks beta-2-mediated bronchodilation|It directly makes new alveoli|It always causes infection|It irreversibly blocks COX-1|A nonselective beta blocker can oppose airway beta-2 effects.~What is a key exercise-monitoring adjustment during beta blockade?|Use exertion and symptoms alongside heart rate|Ignore all cardiovascular signs|Require the same heart rate as an untreated peer|Assume every low heart rate is safe|Heart-rate response may be blunted even when workload is substantial.',
'A patient taking a beta blocker feels heavily exerted despite a modest exercise pulse.|What should the learner conclude?|Heart rate alone may understate workload. Integrate symptoms, perceived exertion, blood pressure, and the prescribed rehabilitation plan.')
C(21,'Antihypertensive Drugs','Autonomic and cardiovascular',4,315,334,'Compare blood-pressure mechanisms and rehabilitation effects.',
'Arterial pressure reflects cardiac output and vascular resistance; antihypertensive classes modify one or more determinants.~Diuretics change renal sodium and water handling. Electrolyte and volume effects differ among thiazide, loop, and potassium-sparing agents.~ACE inhibitors reduce angiotensin II formation; ARBs block its receptor. Cough is associated particularly with ACE inhibition, while potassium and renal effects require attention in both groups.~Beta blockers reduce cardiac sympathetic effects; alpha blockers and central sympatholytics act through other pathways.~Calcium-channel blockers and direct vasodilators reduce vascular tone through different mechanisms; some calcium-channel blockers also slow cardiac conduction.~Common functional concerns include orthostatic hypotension, fatigue, dehydration, and agent-specific electrolyte effects.~Exercise and other nonpharmacological measures can complement management, but medication changes belong to the prescribing team.',
'Diuretics|Hydrochlorothiazide; furosemide; spironolactone|Alter sodium and fluid handling|Volume depletion; differing potassium effects~Renin-angiotensin agents|Lisinopril; losartan|Reduce angiotensin-mediated effects|Potassium and renal effects; ACE-inhibitor cough~Other BP agents|Amlodipine; metoprolol; prazosin|Reduce vascular tone or cardiac drive|Edema; bradycardia; orthostasis depending on class',
'Use gradual position changes and monitor postural symptoms.~Consider additive vasodilation with systemic heat or a hot therapeutic pool.~Monitor exercise response and report weakness, cramps, or dizziness that may signal fluid or electrolyte problems.',
'All diuretics do not lower potassium; potassium-sparing drugs can raise it.',
'What two major determinants influence arterial pressure?|Cardiac output and vascular resistance.~Which class commonly causes cough?|ACE inhibitors.~Why is systemic heat relevant?|Heat-related vasodilation may add to medication-related blood-pressure lowering.',
'Which drug is potassium-sparing?|Spironolactone|Furosemide|Hydrochlorothiazide|Acetaminophen|Spironolactone differs from potassium-wasting diuretics and can raise potassium.~Why might a hot pool increase dizziness with vasodilator therapy?|Additive vasodilation may lower blood pressure|Heat always blocks drug absorption|The pool raises every drug clearance equally|All antihypertensives become inactive in water|Systemic heat and vasodilating medication can combine to impair postural tolerance.',
'A patient becomes lightheaded when standing after pool therapy while taking antihypertensives.|What relationship should be reviewed?|The combined effects of heat, vasodilation, volume status, and position change. Stop and assess safely and communicate significant symptoms.')
C(22,'Treatment of Angina Pectoris','Autonomic and cardiovascular',4,335,348,'Connect antianginal therapy to oxygen supply and demand.',
'Angina reflects myocardial oxygen supply that is insufficient relative to demand; stable, vasospastic, and unstable presentations are not interchangeable.~Nitrates generate nitric-oxide-related smooth-muscle relaxation and reduce cardiac workload, especially through venodilation.~Beta blockers reduce heart rate and contractility, lowering oxygen demand.~Calcium-channel blockers can reduce workload and relieve coronary spasm; cardiac and vascular effects depend on the agent.~Nitrate headache, dizziness, hypotension, and tolerance are relevant; formulation and dosing strategies belong to the prescribed plan.~Nitrates have a dangerous hypotensive interaction with PDE-5 inhibitors. Medication reconciliation must include drugs used outside the cardiac regimen.~New, worsening, or rest chest symptoms require appropriate urgent assessment rather than routine exercise progression.',
'Nitrates|Nitroglycerin; isosorbide preparations|NO-related vasodilation and reduced preload|Headache; hypotension; important interactions~Beta blockers|Metoprolol; atenolol|Reduce cardiac oxygen demand|Bradycardia; reduced exercise heart-rate response~Calcium-channel blockers|Diltiazem; verapamil; amlodipine|Agent-specific coronary and workload effects|Hypotension; edema; conduction effects',
'Know the individual emergency and prescribed angina response plan before exercise.~Monitor symptoms, workload, and hemodynamics rather than chasing an untreated target pulse.~Stop activity and escalate new or concerning chest symptoms according to the clinical setting.',
'Not every calcium-channel blocker has the same effect on heart rate or conduction.',
'What is the supply-demand model of angina?|Myocardial oxygen demand exceeds available supply.~How do beta blockers help?|They reduce heart rate and contractility, lowering demand.~Why ask about PDE-5 inhibitors with nitrates?|The combination can cause dangerous hypotension.',
'Which change primarily lowers myocardial oxygen demand?|Reduced heart rate and contractility|Increased resting cardiac workload|Increased afterload in every case|Uncontrolled tachycardia|Lower cardiac work reduces oxygen consumption.~Which combination is a major hypotension concern?|A nitrate with a PDE-5 inhibitor|A nitrate with a written symptom diary|A beta blocker with a gait aid|A calcium-channel blocker with a chair|Both drug actions can markedly amplify vasodilation.',
'A patient develops new chest pressure during a previously tolerated workload.|What is the appropriate educational takeaway?|Stop activity and activate the appropriate assessment plan. Do not assume chronic antianginal therapy makes new symptoms benign.')
C(23,'Treatment of Cardiac Arrhythmias','Autonomic and cardiovascular',4,349,358,'Understand rhythm control and the risk of proarrhythmia.',
'Arrhythmias arise from altered impulse formation or conduction. Drug selection depends on the rhythm and underlying cardiac condition.~The classic classification includes class I sodium-channel blockers, class II beta blockers, class III repolarization-prolonging drugs, and class IV selected calcium-channel blockers.~Class I agents have subgroups with different conduction and repolarization effects; the class label alone is not a full prediction.~Class II and selected class IV drugs can slow nodal conduction. Dihydropyridine calcium-channel blockers are not interchangeable with verapamil or diltiazem for this purpose.~Antiarrhythmic drugs can themselves provoke arrhythmias; therapeutic rhythm control does not eliminate the need for monitoring.~Amiodarone has multiple electrophysiological effects and important extracardiac toxicities, including pulmonary and thyroid effects.~Other agents, such as adenosine and digoxin, have indication-specific rhythm uses outside a simple four-class summary.',
'Classes I and III|Lidocaine; flecainide; amiodarone; sotalol|Modify sodium conduction or repolarization|Proarrhythmia and agent-specific toxicity~Classes II and IV|Beta blockers; verapamil; diltiazem|Reduce sympathetic or calcium-dependent nodal effects|Bradycardia; hypotension; conduction block',
'Report new palpitations, syncope, chest symptoms, or unexpected exertional intolerance.~Monitor pulse and hemodynamic response within the prescribed rehabilitation plan.~Consider a drug-related explanation for new respiratory symptoms as well as cardiac or pulmonary disease.',
'An antiarrhythmic can cause an arrhythmia; its name is not a safety guarantee.',
'What is proarrhythmia?|A drug-induced new or worsened arrhythmia.~Which classic class includes beta blockers?|Class II.~Why is amiodarone relevant beyond the ECG?|It can affect organs such as the lungs and thyroid.',
'Which calcium-channel blockers have important nodal effects?|Verapamil and diltiazem|Every topical calcium supplement|Amlodipine and nifedipine exclusively|All antacids|Nondihydropyridine agents affect nodal conduction more than typical dihydropyridines.~What does proarrhythmia mean?|An arrhythmia caused or worsened by treatment|Guaranteed normal sinus rhythm|Only a slow respiratory rate|Increased calcium absorption|Antiarrhythmic treatment can paradoxically produce hazardous rhythm changes.',
'A patient on rhythm medication develops near-syncope with exercise.|What must not be assumed?|Do not assume the medication prevents all rhythm problems. Stop, assess, and escalate according to the clinical protocol.')
C(24,'Treatment of Congestive Heart Failure','Autonomic and cardiovascular',4,359,374,'Separate symptom relief from modification of harmful neurohormonal activity.',
'Heart failure impairs effective cardiac pumping and may produce congestion, fatigue, and reduced exercise tolerance.~Compensatory sympathetic and renin-angiotensin activity can become harmful by increasing workload and remodeling.~The fifth-edition discussion emphasizes ACE inhibitors and selected beta blockers as ways to oppose harmful neurohormonal effects; this is a historical textbook framework rather than a complete current regimen.~Diuretics relieve congestion but can alter volume and electrolytes. Vasodilators can reduce preload or afterload depending on the agent.~Digoxin increases contractile force through sodium-potassium ATPase-related effects and also influences conduction; it has a narrow therapeutic range.~Digoxin toxicity may involve GI symptoms, confusion, visual changes, and arrhythmias; kidney function and potassium disturbances matter.~Different heart-failure phenotypes and stability states require different treatment and exercise plans.',
'Neurohormonal agents|ACE inhibitors; selected beta blockers; aldosterone antagonists|Oppose maladaptive signaling|BP; renal; potassium; tolerance considerations~Symptom-directed agents|Loop diuretics; selected vasodilators|Reduce congestion or hemodynamic load|Volume depletion; electrolytes; hypotension~Cardiac glycoside|Digoxin|Inhibits sodium-potassium ATPase and alters conduction|Narrow margin; arrhythmias; toxicity',
'Follow weight, edema, dyspnea, and activity tolerance trends within the care plan.~Report sudden worsening congestion, breathlessness, or marked fatigue.~Consider electrolyte and renal factors when new symptoms occur during digoxin or diuretic therapy.',
'A drug that relieves congestion does not necessarily have the same outcome benefits as a disease-modifying drug.',
'Why can neurohormonal compensation become harmful?|Persistent activation increases cardiac workload and adverse remodeling.~What is a major digoxin concern?|Its narrow therapeutic range and potential for arrhythmias.~Why is this chapter not a complete current prescribing algorithm?|It reflects the fifth-edition treatment framework published in 2016.',
'Which medicine has a narrow margin and can cause visual, GI, and rhythm toxicity?|Digoxin|A plain emollient|Topical miconazole alone|An inert tablet filler|Digoxin exposure must be interpreted with kidney function, interactions, and electrolytes.~What is a primary symptom-directed benefit of a loop diuretic in congestion?|Reduced fluid overload|Guaranteed restoration of all cardiac cells|Permanent elimination of every arrhythmia|Increased blood volume|Diuresis reduces fluid burden but can also deplete volume and electrolytes.',
'A patient on a diuretic and digoxin develops nausea, unusual visual symptoms, and a new irregular pulse.|What should be done with this observation?|Stop and obtain clinical assessment for possible toxicity or electrolyte-related rhythm problems rather than progressing exercise.')
C(25,'Coagulation Disorders and Hyperlipidemia','Autonomic and cardiovascular',4,375,396,'Distinguish platelet inhibition, anticoagulation, clot lysis, and lipid lowering.',
'Hemostasis balances bleeding prevention against inappropriate thrombosis. Platelets and coagulation factors represent related but distinct targets.~Heparins enhance antithrombin-related effects; warfarin interferes with vitamin-K-dependent factor production.~Direct thrombin and factor Xa inhibitors inhibit specific coagulation enzymes; monitoring requirements are agent-specific.~Antiplatelet drugs reduce platelet activation or aggregation. They do not have identical indications or monitoring to anticoagulants.~Fibrinolytic drugs promote breakdown of existing fibrin clots; this differs from preventing further clot formation.~Bleeding risk affects handling, falls, and invasive procedures. INR is primarily a warfarin-related measure, not a universal test for every anticoagulant.~Statins lower cholesterol through HMG-CoA reductase inhibition. Myalgia, weakness, and rare severe muscle injury warrant attention; other lipid drugs act differently.',
'Anticoagulants|Heparin; warfarin; rivaroxaban; dabigatran|Reduce coagulation by different targets|Bleeding; interactions; agent-specific monitoring~Antiplatelet and fibrinolytic agents|Aspirin; clopidogrel; alteplase|Reduce platelet activity or lyse fibrin|Bleeding; distinct clinical roles~Lipid-lowering drugs|Statins; ezetimibe; fibrates|Reduce lipid production, absorption, or modify metabolism|Agent-specific muscle and hepatic effects',
'Modify techniques to reduce unnecessary tissue trauma in patients with bleeding risk.~Escalate suspected DVT or pulmonary embolism rather than treating it as routine muscle soreness.~Report unexplained muscle pain or weakness during statin therapy, particularly if severe or accompanied by systemic symptoms.',
'INR does not quantify the effect of all anticoagulants, and anticoagulation does not immediately dissolve a clot.',
'Which drug class breaks down an existing fibrin clot?|Fibrinolytics.~What does INR mainly guide in this context?|Warfarin monitoring.~Why can a statin matter in a strength assessment?|Drug-related muscle symptoms may contribute to pain or weakness.',
'Which drug class directly promotes breakdown of fibrin in an existing clot?|Fibrinolytics|Antacids|Beta-2 agonists|Antimuscarinics|Fibrinolysis differs from inhibiting new clot formation.~Which measurement is chiefly associated with warfarin management?|INR|Peak expiratory flow|Visual acuity|A fasting temperature alone|INR reflects vitamin-K-antagonist effects and is not a universal anticoagulant assay.',
'A patient on a statin reports new generalized muscle pain rather than expected local exercise soreness.|What should be reviewed?|Document timing, distribution, severity, medication changes, and systemic features, then coordinate medical review for possible drug-related muscle effects.')
C(26,'Respiratory Drugs','Respiratory and gastrointestinal',5,399,420,'Distinguish bronchodilation, inflammation control, and secretion management.',
'Bronchodilators relax airway smooth muscle; anti-inflammatory agents address the inflammatory component of airway disease.~Beta-2 agonists vary in onset and duration. A maintenance drug should not be assumed to substitute for a prescribed acute-relief plan.~Inhaled antimuscarinics reduce cholinergic bronchoconstriction; xanthines such as theophylline have bronchodilator actions but important toxicity and interaction concerns.~Inhaled or systemic glucocorticoids reduce inflammation; oral rinsing after inhaled corticosteroids helps reduce local oral adverse effects.~Leukotriene modifiers and cromones act through other pathways. The chapter also covers cough suppressants, decongestants, antihistamines, expectorants, and mucolytics.~Sedating antihistamines can impair alertness and dry secretions; decongestants may increase cardiovascular stimulation.~Suppressing a productive cough can impair clearance in some situations. Effective inhaler use and airway hygiene influence real benefit.',
'Bronchodilators|Albuterol; ipratropium; theophylline|Relax airway smooth muscle through different mechanisms|Tremor; tachycardia; dryness; xanthine toxicity~Anti-inflammatory agents|Inhaled glucocorticoids; leukotriene modifiers|Reduce airway inflammation|Local oral effects; systemic effects vary~Symptom drugs|Antitussives; decongestants; antihistamines|Alter cough, nasal congestion, or allergy symptoms|Sedation; drying; cardiovascular effects',
'Check the individual rescue plan and inhaler technique before exercise sessions.~Coordinate airway-clearance work with the respiratory team.~Do not assume less coughing always means better pulmonary status.',
'An inhaled corticosteroid is not the same thing as a rapid bronchodilator.',
'What is the core difference between a bronchodilator and a steroid?|One relaxes airway smooth muscle; the other reduces inflammation.~Why rinse after an inhaled corticosteroid?|To reduce local oral adverse effects such as candidiasis.~Why may a cough suppressant be problematic?|It can reduce clearance when coughing is needed to remove secretions.',
'Which drug is a beta-2 bronchodilator?|Albuterol|Warfarin|Lithium|Omeprazole|Albuterol relaxes bronchial smooth muscle through beta-2 receptors.~What is a relevant risk of a sedating antihistamine during rehabilitation?|Reduced alertness and drier secretions|Guaranteed greater exercise capacity|Permanent elimination of asthma|Direct dissolution of mucus in every case|Antihistamine sedation and anticholinergic drying can affect participation and secretion management.',
'A patient with retained secretions is coughing less after an OTC cold remedy but breathing less comfortably.|What should be considered?|The product may suppress cough or dry secretions. Assess and communicate the change; reduced coughing alone is not proof of improvement.')
C(27,'Gastrointestinal Drugs','Respiratory and gastrointestinal',5,421,432,'Link acid control and bowel medicines to participation and hydration.',
'Antacids neutralize existing gastric acid; H2 blockers and proton-pump inhibitors reduce acid secretion through different targets.~PPIs inhibit the gastric proton pump; H2 blockers reduce histamine-mediated acid secretion. Ulcer treatment may also require addressing infection or an offending drug.~Magnesium-containing antacids tend toward diarrhea; aluminum-containing products tend toward constipation.~Antidiarrheal agents reduce motility or have other local effects; the cause of diarrhea still matters.~Laxative types include bulk-forming, osmotic, stimulant, and stool-softening approaches, with different mechanisms and fluid needs.~Antiemetics act at different receptors; some cause sedation, extrapyramidal symptoms, or other adverse effects.~The chapter also addresses agents for digestion and bile-related problems. Drug binding and altered GI conditions can influence absorption of other medicines.',
'Acid-related agents|Antacids; famotidine; omeprazole|Neutralize acid or reduce secretion|Bowel changes; interactions; class-specific risks~Bowel agents|Bulk-forming; osmotic; stimulant laxatives; loperamide|Alter stool water or motility|Dehydration; electrolyte changes; constipation~Antiemetics and other GI drugs|Metoclopramide; ondansetron; digestive enzymes|Different motility or receptor effects|Sedation or other agent-specific adverse effects',
'Consider urgency and bowel scheduling when planning treatment.~Diarrhea or laxative overuse can affect hydration and postural tolerance.~Avoid assuming straining and constipation are unrelated to a worsening musculoskeletal complaint.',
'Antacids neutralize acid that is present; PPIs reduce its secretion.',
'What is the PPI target?|The gastric proton pump.~Which antacid component commonly causes constipation?|Aluminum compounds.~Why can GI drugs affect another medication?|They can bind drugs or alter absorption conditions.',
'Which medication class neutralizes existing gastric acid?|Antacids|ACE inhibitors|Beta blockers|Antiseizure drugs|Neutralization differs from suppressing acid secretion.~Which change can follow excessive laxative-related diarrhea?|Fluid and electrolyte loss|Guaranteed improved standing tolerance|Complete absence of interactions|Direct stimulation of bone formation|Loss of fluid and electrolytes can contribute to weakness and dizziness.',
'A patient has dizziness and reduced exercise tolerance during several days of diarrhea after a bowel-medication change.|What relationship should be assessed?|Possible fluid and electrolyte loss, alongside other causes. Document bowel symptoms and coordinate clinical review before progressing activity.')
C(28,'Introduction to Endocrine Pharmacology','Endocrine',5,435,446,'Use feedback and receptor location to understand hormone drugs.',
'Hormones are endogenous signaling chemicals that act at specific target receptors, often after traveling through the circulation.~Hypothalamic and pituitary control links neural input with peripheral endocrine glands.~Negative feedback adjusts hormone release; replacing or suppressing a downstream hormone can affect the entire axis.~Peptide hormones commonly act at membrane receptors; steroid and thyroid hormones commonly regulate intracellular signaling and gene expression.~Endocrine drugs may replace a deficiency, suppress excess production, block hormone action, or use a hormone effect for another therapeutic purpose.~Time course differs across hormone actions: a circulating signal may trigger slower changes in protein synthesis and tissue function.~Pituitary-related pharmacology includes growth hormone, vasopressin-related drugs, and other axis-specific agents; fluid balance and growth/metabolic effects are clinically relevant.',
'Hormone replacement|Insulin; thyroid hormone; adrenal replacement|Restores deficient signaling|Too little and too much can both impair function~Hormone suppression or blockade|Antithyroid agents; receptor antagonists|Reduces excessive hormone effects|Feedback and target-organ consequences',
'Ask whether the drug replaces a deficiency or suppresses excess; this changes the interpretation of symptoms.~Observe energy, fluid balance, temperature tolerance, and activity response.~Endocrine symptoms can evolve slowly and need longitudinal documentation.',
'Giving an exogenous hormone can suppress endogenous production through feedback.',
'What is negative feedback in an endocrine axis?|Downstream hormone effects reduce upstream stimulation.~Where do many peptide hormones act?|At cell-membrane receptors.~Name two endocrine drug strategies.|Replacement of deficient signaling and suppression or blockade of excessive signaling.',
'Which concept explains suppression of endogenous hormone release after replacement?|Negative feedback|Antibacterial resistance|Platelet aggregation|Passive joint motion|A downstream hormonal signal can reduce upstream stimulation.~Which statement about endocrine drugs is correct?|They can replace deficiency or suppress excess|They only act as stimulants|All work exclusively in the stomach|All effects occur instantly|Endocrine pharmacology includes multiple strategies with different time courses.',
'A learner assumes more replacement hormone must always improve energy.|What is missing?|Replacement targets appropriate signaling, not maximal signaling. Excess hormone can be harmful and can alter feedback as well as target-organ function.')
C(29,'Adrenocorticosteroids','Endocrine',5,447,464,'Recall steroid benefit, catabolism, and adrenal suppression together.',
'The adrenal cortex produces glucocorticoids, principally cortisol, and mineralocorticoids, principally aldosterone.~Glucocorticoids alter gene expression and have metabolic, anti-inflammatory, and immunosuppressive effects.~Mineralocorticoids chiefly influence sodium, potassium, and fluid balance.~Glucocorticoids may replace deficient adrenal function or treat inflammatory and immune conditions by systemic or local routes.~Chronic exposure can cause proximal muscle weakness, osteoporosis, fragile skin, impaired healing, infection susceptibility, and hyperglycemia.~Suppression of the hypothalamic-pituitary-adrenal axis means abrupt cessation after sufficient exposure can be dangerous; tapering is a prescriber decision.~Local injections may provide strong symptom relief, but tissue vulnerability and the overall exposure profile still matter.',
'Glucocorticoids|Hydrocortisone; prednisone; dexamethasone|Modify inflammatory and metabolic gene signaling|Myopathy; bone loss; infection; adrenal suppression~Mineralocorticoids|Fludrocortisone|Promote sodium retention and influence potassium balance|Fluid retention; BP and electrolyte effects',
'Use progressive strengthening within tissue tolerance and the medical plan.~Protect thin skin and assess fracture risk before aggressive handling or loading.~Report sudden profound weakness, collapse, or other concerning systemic symptoms, especially around steroid interruption or illness.',
'Dramatic pain relief after a steroid does not prove connective tissue can tolerate aggressive stretching.',
'What is the principal human glucocorticoid?|Cortisol.~Why can chronic steroids cause weakness?|Catabolic effects can reduce muscle tissue and proximal strength.~Why can abrupt cessation be dangerous?|Endogenous adrenal function may remain suppressed.',
'Which cluster fits chronic glucocorticoid exposure?|Proximal weakness, fragile skin, and bone loss|Stronger tendons with no infection risk|Guaranteed improved glucose control|Permanent adrenal independence|Glucocorticoid catabolic and immunosuppressive effects can impair rehabilitation.~Who should direct a steroid taper?|The prescribing clinical team|The patient based only on less pain|The exercise app automatically|A classmate without clinical review|Adrenal suppression and disease control require a clinically supervised plan.',
'A patient with long-term prednisone stops it abruptly after symptoms improve.|What should the learner recognize?|Possible adrenal suppression makes unsupervised cessation unsafe. Encourage prompt contact with the prescribing team rather than providing a self-directed taper.')
C(30,'Male and Female Hormones','Endocrine',5,465,490,'Understand reproductive hormones and systemic risks.',
'Androgens, estrogens, and progestins are steroid hormones with reproductive and important systemic effects.~Androgens can be used for selected deficiency states; high-dose anabolic steroid use for performance carries major health risks.~Estrogen and progestin preparations are used for contraception and selected replacement or other clinical purposes.~Hormone exposure can influence bone, muscle, lipids, fluid balance, and cardiovascular or thrombotic risk depending on the agent, route, and patient.~Hormonal cancer therapies may stimulate or block selected pathways; reproductive pharmacology is broader than simple replacement.~Antiandrogens, selective estrogen-receptor modulators, and other hormone-related agents have distinct roles and risk profiles.~Hormonal effects on bone do not justify ignoring vascular symptoms or using hormone therapy as a universal musculoskeletal treatment.',
'Androgen-related drugs|Testosterone; anabolic derivatives; antiandrogens|Modify androgen signaling|Hepatic; endocrine; cardiovascular and behavioral risks vary~Estrogen and progestin drugs|Contraceptive and replacement preparations|Modify reproductive signaling and feedback|Agent- and patient-specific thrombotic concerns~Selective hormone modulators|SERMs; hormone-suppressing cancer therapies|Tissue-selective or suppressive endocrine actions|Bone and systemic effects differ',
'Ask about hormone products and performance-enhancing substances without assuming they are volunteered.~Escalate new unilateral swelling, chest symptoms, or other concerning vascular signs.~Assess bone and muscle effects in the context of the whole regimen.',
'Natural or body-identical hormone language does not establish safety for a specific person.',
'Why ask about anabolic steroid use?|It can affect cardiovascular, hepatic, endocrine, and behavioral health.~Why do hormone drugs matter to bone review?|They can alter bone turnover and bone loss risk.~Does every estrogen-related drug have the same tissue effects?|No; route, compound, and receptor selectivity differ.',
'What is a priority with new unilateral calf swelling during hormone therapy?|Assessment for a possible vascular problem|Automatic reassurance that it is muscle growth|Aggressive massage to test the diagnosis|Assuming all hormones prevent thrombosis|A concerning vascular presentation requires clinical assessment rather than routine treatment.~Which statement about anabolic steroid misuse is sound?|Potential performance gains do not remove serious health risks|It is safe because the body makes androgens|It cannot affect other organs|It always improves tendon integrity|Supraphysiological use can carry substantial systemic harms.',
'A patient using hormonal medication reports new one-sided leg swelling and calf discomfort.|What should the reviewer teach?|Recognize a possible thrombotic warning presentation and seek appropriate assessment; do not diagnose or exclude DVT through a single stretch or symptom test.')
C(31,'Thyroid, Parathyroid, and Bone-Mineral Drugs','Endocrine',5,491,506,'Link metabolic rate, calcium balance, and fracture prevention.',
'Thyroid T3 and T4 regulate metabolism, growth, and development. Too little or too much thyroid activity changes energy and exercise tolerance.~Levothyroxine replaces deficient thyroid hormone. Antithyroid drugs and other strategies reduce excessive thyroid activity.~Thyroid excess or excessive replacement can contribute to tachycardia, heat intolerance, and bone loss; deficiency can cause fatigue and cold intolerance.~Parathyroid hormone, vitamin D, and calcitonin participate in calcium and bone regulation through different actions.~Vitamin D supports intestinal calcium absorption. Calcium and vitamin D status are foundational considerations but do not replace all osteoporosis therapy.~Bisphosphonates reduce bone resorption; selected hormone-related and anabolic therapies act differently. Drug administration and adverse effects are agent-specific.~Bone benefit should be translated into appropriately graded loading, balance training, and fall prevention.',
'Thyroid agents|Levothyroxine; methimazole; propylthiouracil|Replace hormone or inhibit production|Under- or over-treatment; agent-specific toxicity~Mineral regulators|Calcium; vitamin D; calcitonin|Support mineral balance or modify resorption|Excess and deficiency both matter~Bone-directed therapies|Bisphosphonates; selected PTH analogs|Antiresorptive or anabolic mechanisms|Administration and safety requirements differ',
'Investigate unexplained changes in heat tolerance, pulse, and fatigue.~Use fracture-risk-aware exercise and fall prevention.~Do not assume normal calcium intake alone eliminates osteoporosis risk.',
'PTH physiology and intermittent pharmacological PTH-analog therapy cannot be reduced to one simple bone-loss rule.',
'What does vitamin D facilitate?|Intestinal calcium absorption and normal mineral regulation.~How do bisphosphonates primarily affect bone?|They inhibit bone resorption.~What can excess thyroid hormone do to exercise response?|It can increase heart rate and heat intolerance and contribute to bone loss.',
'Which drug class primarily inhibits bone resorption?|Bisphosphonates|Beta-2 agonists|Antitussives|PPIs as their primary purpose|Bisphosphonates reduce osteoclast-mediated resorption.~Which symptom pattern suggests excessive thyroid activity?|Heat intolerance with tachycardia|Cold intolerance with slowed metabolism only|Absence of any cardiovascular effect|Selective loss of gastric acid|Thyroid excess increases metabolic and cardiovascular activity.',
'A patient on thyroid replacement develops new heat intolerance and a higher resting pulse.|What should be considered?|Possible over-replacement or another medical change. Document the trend and seek review rather than attributing it solely to anxiety or training intensity.')
C(32,'Pancreatic Hormones and Diabetes Mellitus','Endocrine',5,507,528,'Connect insulin, exercise, and hypoglycemia risk.',
'Insulin promotes glucose uptake and storage and influences fat and protein metabolism; glucagon generally helps raise blood glucose.~Type 1 diabetes involves an absolute insulin deficiency; type 2 involves insulin resistance with impaired insulin secretion.~Insulin formulations differ in onset, peak, and duration. Basal and mealtime strategies serve different purposes.~Exercise can increase muscle glucose uptake and insulin sensitivity; insulin or insulin-secretagogue exposure can increase exercise-related hypoglycemia risk, including delayed episodes.~Noninsulin drugs act through different mechanisms: secretagogues, metformin, thiazolidinediones, alpha-glucosidase inhibitors, and incretin-related agents are discussed in the chapter.~Hypoglycemia may cause sweating, tremor, confusion, behavior change, weakness, or reduced consciousness; beta blockade can obscure some warning features.~Assess footwear, sensation, vascular status, and other diabetes complications when planning activity. Medication adjustment must be individualized by the clinical team.',
'Insulin|Rapid-, short-, intermediate-, and long-acting preparations|Replaces or supplements insulin signaling|Hypoglycemia; timing and injection-site effects~Secretagogues|Sulfonylureas; meglitinides|Increase endogenous insulin release|Hypoglycemia~Other glucose-lowering drugs|Metformin; thiazolidinediones; incretin-related drugs|Reduce production, improve sensitivity, or change incretin action|Agent-specific GI, fluid, and other effects',
'Use the patient’s prescribed glucose and exercise safety plan.~Monitor for immediate and delayed symptoms around activity and meals.~Do not independently change insulin doses; coordinate patterns with the diabetes team.',
'Not every glucose-lowering drug causes the same hypoglycemia risk.',
'Why can exercise lower glucose?|Active muscle increases glucose uptake and insulin sensitivity can increase.~Which two broad medication types commonly raise hypoglycemia concern?|Insulin and insulin secretagogues.~Can hypoglycemia occur after exercise ends?|Yes; delayed episodes can occur.',
'Which medicine type directly replaces a missing hormone in type 1 diabetes?|Insulin|A statin|A PPI|An antihistamine|Insulin is required to replace deficient insulin signaling in type 1 diabetes.~Confusion and sweating during activity in an insulin-treated patient should prompt what?|Stop and assess for hypoglycemia using the individual safety plan|Increase exercise immediately|Assume improved conditioning|Independently cancel all future insulin|The symptoms may signal low glucose and require the appropriate response.',
'An insulin-treated student becomes sweaty and confused during exercise.|What is the immediate learning point?|Stop activity, obtain help and glucose assessment according to the safety plan, and treat the event as a possible acute metabolic problem rather than poor motivation.')
C(33,'Treatment of Infections I: Antibacterial Drugs','Infection and oncology',6,531,556,'Organize antibiotics by target and rehabilitation-relevant toxicity.',
'Antibacterials differ in spectrum and whether they inhibit growth or kill susceptible bacteria. Culture, infection site, and resistance influence selection.~Beta-lactams and glycopeptides act on cell-wall synthesis; protein-synthesis inhibitors act at bacterial ribosomal targets.~Fluoroquinolones affect bacterial DNA enzymes; other agents target nucleic acid synthesis or folate pathways.~Resistance can arise through altered targets, drug inactivation, decreased entry, or increased efflux; broad-spectrum does not mean universally superior.~Hypersensitivity, GI disturbance, superinfection, and organ-specific toxicity can complicate treatment.~Fluoroquinolones can be associated with tendon injury. Aminoglycosides can affect hearing, vestibular function, kidneys, and neuromuscular transmission.~Some antibiotics cause photosensitivity, relevant to UV exposure and treatment modalities.',
'Cell-wall inhibitors|Penicillins; cephalosporins; vancomycin|Disrupt bacterial wall synthesis|Hypersensitivity; agent-specific renal effects~Protein-synthesis inhibitors|Aminoglycosides; tetracyclines; macrolides|Act at bacterial ribosomal targets|Ototoxicity; interactions; photosensitivity vary~Nucleic-acid and metabolic agents|Fluoroquinolones; sulfonamides|Alter DNA-related or folate processes|Tendon risk; photosensitivity; agent-specific effects',
'New tendon pain during fluoroquinolone exposure warrants prompt review and loading caution.~Consider vestibular drug toxicity when balance deteriorates.~Check photosensitivity concerns before ultraviolet exposure and follow infection-control measures.',
'Antibiotics do not treat every viral infection, and broader spectrum is not automatically better.',
'Which antibiotic group is associated with tendon injury?|Fluoroquinolones.~Why can an aminoglycoside matter in balance therapy?|Vestibular toxicity can impair balance.~What is bacterial resistance?|Reduced susceptibility to a drug through microbial adaptations.',
'Which new symptom is especially relevant during ciprofloxacin exposure?|Achilles tendon pain|Guaranteed increased tendon strength|Only a change in hair color|Permanent immunity to infection|Fluoroquinolone-related tendon injury is a key rehabilitation concern.~Which class can produce vestibular toxicity?|Aminoglycosides|PPIs|Antacids|Bisphosphonates|Aminoglycosides can damage vestibular function and complicate balance.',
'A runner taking ciprofloxacin develops Achilles pain after a modest training increase.|What should the learner avoid assuming?|Do not attribute it automatically to training. Consider drug-associated tendon injury, protect from provocative loading, and arrange prompt medical review.')
C(34,'Treatment of Infections II: Antiviral Drugs','Infection and oncology',6,557,580,'Match antiviral strategies to the viral life cycle.',
'Viruses depend on host cells, making selective antiviral treatment difficult. Antivirals often inhibit specific stages of viral entry, replication, or release.~Herpesvirus drugs such as acyclovir act on viral DNA-related processes; activity depends on the virus and drug.~Influenza therapies have virus- and mechanism-specific roles; a drug for one virus does not treat all viral syndromes.~HIV therapy combines agents with different targets, including reverse transcriptase, protease, integrase, or entry-related steps.~Combination therapy and adherence reduce opportunities for resistant viral replication; resistance remains a major limitation.~Adverse effects can include fatigue, GI symptoms, neuropathy, myopathy, metabolic changes, or marrow effects depending on the agent.~Vaccination prevents selected infections through immune priming; it is not identical to directly inhibiting viral replication. The chapter’s specific regimens are historical.',
'Herpes and other virus-specific agents|Acyclovir; ganciclovir; selected influenza agents|Inhibit specific viral processes|Renal, marrow, and other effects vary~Antiretrovirals|NRTIs; NNRTIs; protease; integrase; entry inhibitors|Target different HIV life-cycle stages|Interactions; neuropathy; metabolic or muscle effects',
'Adapt intensity to fatigue and systemic status rather than diagnosis alone.~Assess sensory loss and weakness when neuropathy or myopathy is possible.~Use appropriate infection-control practices and support adherence through the clinical team.',
'Antiviral activity is virus-specific; an antiviral is not a universal anti-infection drug.',
'Why combine drugs in HIV treatment?|Different targets suppress replication and reduce resistance opportunities.~Why is antiviral selectivity challenging?|Viruses rely on host-cell machinery.~Why may an antiviral regimen affect rehabilitation?|Fatigue, neuropathy, myopathy, and other adverse effects can alter function.',
'What is a key reason for combination antiretroviral therapy?|Suppress replication at multiple targets and limit resistance|Make every viral infection immediately curable|Eliminate all drug interactions|Remove the need for adherence|Multiple active mechanisms reduce viral replication and resistance risk.~Which statement about vaccination is correct?|It primes immune protection against selected infections|It is identical to every antiviral drug|It treats all established viral disease immediately|It has no relationship to immunity|Prevention through immune priming differs from direct antiviral inhibition.',
'A patient with HIV has new distal sensory symptoms and fatigue while receiving treatment.|What should be considered?|Disease effects, opportunistic conditions, and medication effects may all contribute. Document function and coordinate assessment rather than assigning a single cause automatically.')
C(35,'Treatment of Infections III: Antifungal and Antiparasitic Drugs','Infection and oncology',6,581,598,'Distinguish fungal, protozoal, and worm targets.',
'Antifungal, antiprotozoal, and anthelmintic agents treat different organisms; they are not interchangeable categories.~Many antifungals target ergosterol or its synthesis in fungal membranes. Echinocandins act on fungal cell-wall components.~Topical therapy can treat selected superficial infections; systemic infection often requires systemic therapy and closer toxicity monitoring.~Amphotericin B can cause renal and electrolyte problems; azoles have important hepatic and drug-interaction considerations.~Antiprotozoal treatment includes organism-specific drugs for malaria and other protozoal infections. Geography and resistance influence the appropriate regimen.~Anthelmintics act through parasite-specific metabolic or neuromuscular mechanisms; worm type and location matter.~Immunocompromised patients may have opportunistic infections and complex medication profiles.',
'Antifungals|Azoles; amphotericin B; echinocandins|Alter fungal membrane or cell-wall function|Renal; electrolyte; hepatic and interaction risks~Antiprotozoals|Selected antimalarials; metronidazole|Organism-specific metabolic and other targets|Toxicity and resistance depend on drug~Anthelmintics|Albendazole; praziquantel; ivermectin|Disrupt parasite metabolism or neuromuscular function|Organism- and agent-specific precautions',
'Use hygiene and equipment-cleaning measures for superficial fungal infection.~Consider electrolyte disturbance and systemic fatigue when activity tolerance worsens.~Check interactions and clinical guidance before attributing symptoms to infection alone.',
'A superficial infection treatment plan cannot be generalized to an invasive fungal infection.',
'What fungal membrane component is a common drug target?|Ergosterol or its synthesis.~What is an anthelmintic used against?|Parasitic worms.~Why is amphotericin B relevant to exercise tolerance?|Renal and electrolyte adverse effects may contribute to weakness and systemic symptoms.',
'Which drug group treats parasitic worms?|Anthelmintics|Antacids|Beta blockers|Antihistamines as their primary role|Anthelmintics target helminth infections.~Which complication is associated with amphotericin B?|Renal and electrolyte toxicity|Guaranteed muscle hypertrophy|Permanent bronchodilation|Selective platelet production|Its systemic toxicity can affect hydration, electrolytes, and function.',
'An athlete receiving topical antifungal treatment asks about preventing spread in the training room.|What belongs in the reviewer?|Follow the prescribed application plan, keep shared environments and equipment hygienic, and address moisture and skin care without sharing medication.')
C(36,'Cancer Chemotherapy','Infection and oncology',6,599,624,'Translate treatment toxicity into flexible, safe rehabilitation.',
'Traditional antineoplastic drugs impair DNA synthesis, DNA function, or cell division; rapidly renewing normal tissues can also be harmed.~Major groups include alkylating agents, antimetabolites, antitumor antibiotics, microtubule agents, and topoisomerase inhibitors.~Cell-cycle specificity helps explain scheduling and combination strategies, but clinical regimens depend on the malignancy and patient.~Targeted, biological, and hormone-related therapies act through more selected pathways but can still cause serious toxicity.~Marrow suppression can produce anemia, neutropenia, and thrombocytopenia, affecting endurance, infection risk, and bleeding risk.~Peripheral neuropathy, fatigue, GI symptoms, and drug-specific cardiac or pulmonary toxicity can limit function.~Treatment cycles can create changing tolerance across days; decisions must use actual symptoms, blood counts, and oncology guidance rather than a universal exercise cutoff.',
'Cytotoxic drugs|Alkylators; antimetabolites; taxanes; vinca agents|Disrupt DNA processes or mitosis|Marrow suppression; neuropathy; tissue-specific toxicity~Targeted and biological therapies|Selected kinase inhibitors; antibodies|Target selected tumor or signaling features|Serious agent-specific organ effects remain~Hormone-related strategies|Antiestrogens; androgen suppression|Alter hormone-dependent tumor signaling|Bone; muscle; metabolic effects',
'Coordinate exercise with the oncology plan and current clinical status.~Modify contact, loading, and exposure when bleeding or infection risk is elevated.~Reassess balance, sensation, fatigue, and cardiopulmonary symptoms across treatment cycles.',
'Targeted therapy is not synonymous with toxicity-free therapy.',
'Why does chemotherapy cause marrow suppression?|Normal rapidly dividing marrow cells can also be affected.~How does thrombocytopenia affect rehabilitation?|It raises bleeding concern and may change appropriate activity or handling.~Why track treatment-cycle timing?|Adverse effects and capacity can fluctuate during the cycle.',
'Which blood-cell problem most directly increases bleeding risk?|Thrombocytopenia|Neutropenia|Anemia alone|An elevated thyroid hormone level|Low platelets impair hemostatic capacity.~What is the best basis for exercise modification during chemotherapy?|Current symptoms, clinical measures, and oncology guidance|A single universal rule for every patient|The assumption that targeted drugs have no toxicity|Medication brand color|Tolerance depends on individual disease, treatment, counts, and symptoms.',
'A patient has greater fatigue and new distal numbness during a chemotherapy cycle.|How should rehabilitation respond?|Reassess endurance, balance, sensation, and treatment-related risks, adapt tasks, and share new symptoms with the oncology team.')
C(37,'Immunomodulating Agents','Infection and oncology',7,625,640,'Contrast immune suppression and stimulation.',
'Immune-modifying drugs may suppress harmful or unwanted immunity or enhance selected immune responses.~Immunosuppression is central to transplant rejection prevention and treatment of selected autoimmune diseases.~Glucocorticoids suppress multiple immune pathways but also have systemic catabolic and metabolic effects.~Calcineurin inhibitors, antimetabolites, mTOR-related agents, antibodies, and fusion proteins target different immune processes.~Reduced immune activity can increase infection susceptibility and some long-term risks; agent-specific renal, marrow, and other toxicity also matter.~Immunoglobulins, cytokines, and other immunostimulatory strategies have context-specific roles; stimulation is not uniformly beneficial.~Successful disease control or transplantation does not remove medication-related risks to bone, muscle, skin, and wound healing.',
'Immunosuppressants|Cyclosporine; tacrolimus; mycophenolate; sirolimus|Alter lymphocyte signaling or proliferation|Infection; renal or marrow effects vary~Biological immune modifiers|Selected antibodies; fusion proteins|Target specific immune pathways|Infection and agent-specific immune reactions~Other immune strategies|Immunoglobulins; selected cytokines|Modulate or augment particular responses|Systemic and indication-specific adverse effects',
'Use infection-prevention practices and promptly report signs of illness.~Address steroid-related weakness and bone vulnerability with graded rehabilitation.~Coordinate with transplant or specialty teams when exercise capacity or wound status changes.',
'More selective immune targeting does not eliminate infection risk.',
'Why are immunosuppressants used after transplantation?|To reduce immune rejection of the transplanted tissue.~What is a major shared concern with immune suppression?|Increased susceptibility to infection.~Why can transplant rehabilitation involve bone and muscle precautions?|Glucocorticoids and other factors can contribute to tissue loss and weakness.',
'What is a major goal of a transplant immunosuppressive regimen?|Prevent rejection|Enhance rejection|Eliminate all need for monitoring|Guarantee immediate muscle recovery|Suppressing immune responses can protect the transplanted tissue.~Which new finding should be communicated promptly in an immunosuppressed patient?|Possible infection symptoms|An improved walking score alone|A preference for morning exercise|A change in shoe brand|Reduced immune defense makes timely infection assessment important.',
'A transplant recipient is gaining mobility but develops fever and unusual fatigue.|What takes priority?|Prompt clinical review for possible infection or another complication, followed by adjustment of rehabilitation with the specialty team.')
C(38,'Complementary and Alternative Medications','Integration',7,641,656,'Treat supplements as pharmacologically active exposures.',
'Complementary and alternative medications include diverse herbs and nutritional supplements; products differ in evidence, purity, and formulation.~Natural origin does not establish safety, effectiveness, or consistent dosing.~Supplements may cause direct toxicity or interact with prescribed medicines through metabolic, platelet, sedative, or other mechanisms.~St. John’s wort can induce metabolism of susceptible drugs and reduce their effectiveness, including the warfarin interaction discussed in the chapter.~Ginkgo, garlic, and other products may influence bleeding-related risk; sedating products may add to CNS depressants.~Evidence should be assessed for the actual product, indication, outcomes, and safety rather than relying on testimonials or a class-wide assumption.~Ask specifically about teas, powders, sports products, vitamins, and herbs because patients may not call them medicines.',
'Herbal products|St. John’s wort; ginkgo; garlic|Different enzyme, receptor, or platelet effects|Interactions and variable composition~Nutritional and performance supplements|Vitamins; minerals; mixed sports products|Nutrient replacement or diverse claimed actions|Dose; purity; duplication; undeclared ingredients',
'Include supplements in the medication history and share relevant interactions with the pharmacist or prescriber.~Use neutral questions to encourage accurate disclosure.~Do not recommend discontinuing or replacing a prescription based on an unverified supplement claim.',
'OTC and natural are access or origin descriptions, not evidence of safety.',
'Why ask about herbal teas and powders?|They may contain active substances and cause interactions.~How can St. John’s wort reduce another drug’s effect?|Enzyme induction can increase metabolism of susceptible drugs.~What makes supplement evidence product-specific?|Composition, dose, purity, and studied formulation can vary.',
'Which assumption is unsafe?|Natural products cannot interact with prescriptions|Supplements should be included in medication histories|Evidence can differ by product|Purity affects interpretation|Natural origin does not prevent pharmacological activity or interactions.~What can enzyme induction by St. John’s wort do to a susceptible active drug?|Reduce its exposure and effectiveness|Guarantee a stronger effect|Make all renal clearance stop|Remove every adverse reaction|Increased metabolism may reduce active-drug concentration, as discussed for warfarin.',
'A patient taking warfarin starts St. John’s wort and does not list it as medication.|What should the reviewer emphasize?|Record the supplement and flag the interaction for prompt pharmacist or prescriber review; changes in exposure can undermine anticoagulation even without obvious immediate symptoms.')

DAYS=[
 dict(id=1,title='Build the foundation',subtitle='From dose to receptor to brain',chapters=list(range(1,6)),review=[],goal='Explain potency, exposure, clearance, receptors, and CNS signaling without notes.'),
 dict(id=2,title='Master the nervous system',subtitle='Sleep, mood, seizures, and movement',chapters=list(range(6,11)),review=[1,2,3,4,5],goal='Compare CNS drug classes and recognize sedation, motor effects, and fluctuations.'),
 dict(id=3,title='Control pain. Protect function.',subtitle='Anesthesia, muscle, and inflammation',chapters=list(range(11,18)),review=[6,7,8,9,10],goal='Distinguish analgesia from anesthesia, tone reduction, and disease modification.'),
 dict(id=4,title='Follow the receptors to the heart',subtitle='Autonomic and cardiovascular drugs',chapters=list(range(18,26)),review=[1,3,4,13,14,15],goal='Predict blood-pressure, pulse, airway, bleeding, and exercise-response changes.'),
 dict(id=5,title='Connect the body systems',subtitle='Airways, digestion, and hormones',chapters=list(range(26,33)),review=[18,19,20,21,22,23,24,25],goal='Distinguish airway rescue from control and explain steroid, bone, and glucose effects.'),
 dict(id=6,title='Treat the cause. Track the cost.',subtitle='Infection and oncology',chapters=list(range(33,37)),review=[26,27,28,29,30,31,32],goal='Organize anti-infective and anticancer drugs by target and functional toxicity.'),
 dict(id=7,title='Integrate, retrieve, repeat',subtitle='Immunity, supplements, and final review',chapters=[37,38],review=list(range(1,37)),goal='Connect all systems, complete the mixed exam, and revisit your weakest chapters.')]
for d in DAYS:
 d['newMinutes']=sum(c['minutes'] for c in chapters if c['id'] in d['chapters'])
 d['recallMinutes']=45 if d['id']==7 else 25
